t.script:
document.addEventListener('DOMContentLoaded', function() {
    function updateClock() {
        const now = new Date();
        const clock = document.getElementById('topbar-clock');
        const dateObj = document.getElementById('topbar-date');
        if(clock && dateObj) {
            clock.innerText = now.toLocaleTimeString('vi-VN');
            dateObj.innerText = now.toLocaleDateString('vi-VN');
        }
    }
    setInterval(updateClock, 1000);
    updateClock();

    // Sidebar Toggle Logic
    const desktopBtn = document.getElementById('desktop-sidebar-toggle');
    const mobileBtn = document.getElementById('mobile-sidebar-toggle');
    const mobileCloseBtn = document.getElementById('mobile-sidebar-close');
    const sidebar = document.getElementById('cmcts-sidebar');
    const overlay = document.getElementById('mobile-overlay');

    if(desktopBtn) {
        desktopBtn.addEventListener('click', function() {
            document.body.classList.toggle('sidebar-collapsed');
            localStorage.setItem('cmcts-sidebar-collapsed', document.body.classList.contains('sidebar-collapsed'));
        });
    }

    function toggleMobileSidebar() {
        const isOpen = sidebar.classList.contains('translate-x-0');
        if (isOpen) {
            sidebar.classList.remove('translate-x-0');
            sidebar.classList.add('-translate-x-full');
            overlay.classList.add('hidden');
            setTimeout(() => overlay.classList.remove('opacity-100'), 10);
        } else {
            sidebar.classList.remove('-translate-x-full');
            sidebar.classList.add('translate-x-0');
            overlay.classList.remove('hidden');
            setTimeout(() => overlay.classList.add('opacity-100'), 10);
        }
    }

    if(mobileBtn) mobileBtn.addEventListener('click', toggleMobileSidebar);
    if(mobileCloseBtn) mobileCloseBtn.addEventListener('click', toggleMobileSidebar);
    if(overlay) overlay.addEventListener('click', toggleMobileSidebar);

    // Mobile Search Logic
    const mobileSearchBtn = document.getElementById('mobile-search-toggle');
    const mobileSearchDropdown = document.getElementById('mobile-search-dropdown');
    if(mobileSearchBtn && mobileSearchDropdown) {
        mobileSearchBtn.addEventListener('click', function() {
            mobileSearchDropdown.classList.toggle('hidden');
        });
    }

    // Cart Badge Update Logic
    const cartBtn = document.getElementById('cart-icon-btn');
    if (cartBtn) {
        const cartDataStr = cartBtn.getAttribute('data-cart') || '{}';
        try {
            const cartData = JSON.parse(cartDataStr);
            let totalQty = 0;
            for (const key in cartData) {
                if (cartData.hasOwnProperty(key)) {
                    totalQty += parseInt(cartData[key]) || 0;
                }
            }
            const badge = document.getElementById('cart-badge');
            if (badge && totalQty > 0) {
                badge.innerText = totalQty;
                badge.classList.remove('hidden');
            }
        } catch (e) {
            console.error('Error parsing cart data:', e);
        }
    }
});

xpath.script:
document.addEventListener("DOMContentLoaded", function() {
    function fetchAndReplace(url, method="GET", body=null) {
        let container = document.querySelector("#ajax-content-container");
        if(container) {
            container.style.opacity = '0.5';
            container.style.pointerEvents = 'none';
        }
        fetch(url, {method: method, body: body})
            .then(response => response.text())
            .then(html => {
                let parser = new DOMParser();
                let doc = parser.parseFromString(html, "text/html");
                let newContainer = doc.querySelector("#ajax-content-container");
                if (container && newContainer) {
                    container.innerHTML = newContainer.innerHTML;
                    container.style.opacity = '1';
                    container.style.pointerEvents = 'auto';
                    window.history.pushState({path: url}, '', url);
                    // Re-initialize any necessary scripts here if needed
                } else {
                    window.location.href = url;
                }
            })
            .catch(err => {
                window.location.href = url;
            });
    }

    document.body.addEventListener("click", function(e) {
        let link = e.target.closest("a.ajax-filter");
        if (link) {
            e.preventDefault();
            let url = link.href;
            if (!url || url.includes('#') || url.startsWith('javascript:')) return;
            fetchAndReplace(url);
        }
    });

    document.body.addEventListener("submit", function(e) {
        let form = e.target.closest("form.ajax-form");
        if (form) {
            e.preventDefault();
            let url = new URL(form.action);
            let formData = new FormData(form);
            if (form.method.toUpperCase() === "GET") {
                for (let [key, value] of formData.entries()) {
                    if(value) url.searchParams.set(key, value);
                }
                fetchAndReplace(url.toString());
            } else {
                fetchAndReplace(url.toString(), "POST", formData);
            }
        }
    });

    window.addEventListener("popstate", function() {
        window.location.reload();
    });
});
